const REFERENCE_START = Date.UTC(2026, 0, 1);
const DAY_MS = 86_400_000;

export function getReferenceActionAdvice(date: string): ReferenceActionAdvice[] | null {
  const match = date.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const index = Math.floor((Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])) - REFERENCE_START) / DAY_MS);
  const rows = REFERENCE_DAYS[index];
  if (!rows) return null;
  return rows.map(([activityIndex, isGood, score, goodFactors, badFactors, goodHours]) => ({
    name: ACTIVITY_NAMES[activityIndex],
    status: isGood ? "suitable" : "avoid",
    score,
    guidance: isGood ? "Cát khí theo loại việc đang chiếm ưu thế" : "Có yếu tố kỵ riêng cho loại việc này",
    goodStars: goodFactors.map((factorIndex) => FACTOR_NAMES[factorIndex]).join(", "),
    badStars: badFactors.map((factorIndex) => FACTOR_NAMES[factorIndex]).join(", "),
    goodHours: isGood ? goodHours.map((branchIndex) => BRANCH_NAMES[branchIndex]) : undefined,
  }));
}
